package glitch

import data.glitch_lib

# Weak encryption algorithms and ciphers
weak_algorithms := {"DES", "3DES", "des", "3des", "RC2", "RC4", "rc2", "rc4", "IDEA", "idea", "Blowfish", "blowfish", "MD5", "md5", "SHA1", "sha1", "SHA-1", "sha-1"}

# Weak TLS/SSL versions
weak_tls_versions := {"1.0", "1.1", "SSLv2", "SSLv3", "sslv2", "sslv3", "TLSv1.0", "TLSv1.1", "tlsv1.0", "tlsv1.1"}

# Deprecated protocol names
deprecated_protocols := {"SSLv2", "SSLv3", "TLSv1.0", "TLSv1.1", "tls_1_0", "tls_1_1", "ssl_2", "ssl_3"}

# Weak curve names
weak_curves := {"secp128", "secp160", "secp192", "prime192v1", "secp192r1"}

# Encryption-related attribute names
encryption_attrs := {"algorithm", "cipher", "encryption_method", "crypto_algorithm", "sse_algorithm", "encryption_type", "password_hash_algorithm", "hash_function", "tls_version_minimum", "ssl_policy", "protocol_version", "cipher_suites", "min_tls_version", "security_policy", "certificate_key_algorithm"}

# Key size-related attribute names
key_size_attrs := {"key_size", "key_length", "bits", "key_bits", "minimum_key_size", "rsa_key_size"}

# Check if a string contains any weak algorithm
contains_weak_algorithm(value) {
    algorithm := weak_algorithms[_]
    regex.match(sprintf("(?i).*\\b%s\\b.*", [algorithm]), value)
}

# Check if a string contains any weak TLS version
contains_weak_tls_version(value) {
    version := weak_tls_versions[_]
    regex.match(sprintf(".*%s.*", [version]), value)
}

# Check if a string contains any deprecated protocol
contains_deprecated_protocol(value) {
    protocol := deprecated_protocols[_]
    regex.match(sprintf("(?i).*\\b%s\\b.*", [protocol]), value)
}

# Check if a string contains any weak curve
contains_weak_curve(value) {
    curve := weak_curves[_]
    regex.match(sprintf("(?i).*\\b%s\\b.*", [curve]), value)
}

# Extract numeric value from a string (e.g., "128" from "128-bit" or "AES-128")
extract_numeric(str) = num {
    # Try to find a number at the start
    regex.match("^[0-9]+", str, matches)
    num = to_number(matches[0])
} else = num {
    # Try to find a number after a dash
    regex.find_n("-(\\d+)", str, 1, matches)
    num = to_number(matches[0])
} else = num {
    # Try to find any number
    regex.find_n("(\\d+)", str, 1, matches)
    num = to_number(matches[0])
} else = null {
    true
}

# Check if value indicates weak key size
is_weak_key_size(value, attr_name) {
    value.ir_type == "Integer"
    value.value < 2048
    contains(attr_name, "rsa")
} else {
    value.ir_type == "Integer"
    value.value < 224
    contains(attr_name, "ec")
} else {
    value.ir_type == "Integer"
    value.value < 128
    not contains(attr_name, "rsa")
    not contains(attr_name, "ec")
} else {
    value.ir_type == "String"
    num := extract_numeric(value.value)
    num != null
    num < 2048
    contains(attr_name, "rsa")
} else {
    value.ir_type == "String"
    num := extract_numeric(value.value)
    num != null
    num < 224
    contains(attr_name, "ec")
} else {
    value.ir_type == "String"
    num := extract_numeric(value.value)
    num != null
    num < 128
    not contains(attr_name, "rsa")
    not contains(attr_name, "ec")
}

# Check for weak algorithm in any value type
has_weak_algorithm_value(value) {
    value.ir_type == "String"
    contains_weak_algorithm(value.value)
} else {
    value.ir_type == "VariableReference"
    contains_weak_algorithm(value.value)
}

# Check for weak TLS version in any value type
has_weak_tls_value(value) {
    value.ir_type == "String"
    contains_weak_tls_version(value.value)
} else {
    value.ir_type == "VariableReference"
    contains_weak_tls_version(value.value)
}

# Check for null or empty encryption
is_null_or_empty_encryption(value) {
    value.ir_type == "Null"
} else {
    value.ir_type == "Undef"
} else {
    value.ir_type == "Boolean"
    value.value == false
}

# Recursively check values in complex types for weak encryption
deep_check_weak_crypto(value) {
    has_weak_algorithm_value(value)
} else {
    value.ir_type == "Hash"
    some k, v
    value.value[k] = v
    deep_check_weak_crypto(v)
} else {
    value.ir_type == "Array"
    some v
    v = value.value[_]
    deep_check_weak_crypto(v)
} else {
    value.ir_type == "BlockExpr"
    some stmt
    stmt = value.statements[_]
    deep_check_weak_crypto(stmt)
}

# Recursively check for weak key sizes in complex types
deep_check_weak_key_size(value, attr_name) {
    is_weak_key_size(value, attr_name)
} else {
    value.ir_type == "Hash"
    some k, v
    value.value[k] = v
    deep_check_weak_key_size(v, attr_name)
} else {
    value.ir_type == "Array"
    some v
    v = value.value[_]
    deep_check_weak_key_size(v, attr_name)
}

# Main detection rule: weak algorithm in encryption attribute
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    encryption_attrs[_] == attr.name
    deep_check_weak_crypto(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Use of weak or deprecated cryptographic algorithm. (CWE-326)"
    }
}

# Detection rule: insufficient key size
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    attr.name == key_size_attrs[_]
    deep_check_weak_key_size(attr.value, attr.name)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Insufficient key size for cryptographic operation. (CWE-326)"
    }
}

# Detection rule: weak TLS/SSL configuration
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    tls_attrs := {"tls_version_minimum", "min_tls_version", "ssl_policy", "protocol_version"}
    tls_attrs[_] == attr.name
    has_weak_tls_value(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Use of weak TLS/SSL version. (CWE-326)"
    }
}

# Detection rule: disabled or null encryption
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    enable_encryption_attrs := {"encrypted", "storage_encrypted", "encryption", "transparent_data_encryption", "TDE", "storage_encryption"}
    enable_encryption_attrs[_] == attr.name
    is_null_or_empty_encryption(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Encryption is disabled or not explicitly configured. (CWE-326)"
    }
}

# Detection rule: weak cipher in string values (general check)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check string values that might contain cipher configurations
    attr.value.ir_type == "String"
    value_str := attr.value.value

    # Check for weak algorithm mentions in any attribute
    contains_weak_algorithm(value_str)

    # Not already covered by specific encryption attribute rules
    not attr.name == encryption_attrs[_]

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Use of weak or deprecated cryptographic algorithm in configuration. (CWE-326)"
    }
}

# Detection rule: deprecated protocol in configuration names
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
