    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    curve_attrs := {"ecdsa_curve", "elliptic_curve", "curve", "named_curve"}
    curve_attrs[_] == attr.name
    attr.value.ir_type == "String"
    contains_weak_curve(attr.value.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Use of weak elliptic curve for cryptographic operations. (CWE-326)"
    }
}

